import React, { useState, useContext } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import { OrderContext } from "./OrderContext";
import backgroundImage from "../Img/order8.jpg";

const AddOrder = () => {
  const [orderData, setOrderData] = useState({
    firstName: "",
    lastName: "",
    email: "",
    phoneNumber: "",
    address: "",
    city: "",
    orderId: "",
    specialInstructions: "",
    pickupTime: "",
    orderStatus: "",
  });

  const [errors, setErrors] = useState({});
  const { setOrdersChanged } = useContext(OrderContext);
  const navigate = useNavigate();

  const validateForm = () => {
    let newErrors = {};
    if (!orderData.firstName.trim()) newErrors.firstName = "First Name is required.";
    if (!orderData.lastName.trim()) newErrors.lastName = "Last Name is required.";
    if (!orderData.email.trim() || !/\S+@\S+\.\S+/.test(orderData.email)) newErrors.email = "Enter a valid email.";
    if (!orderData.phoneNumber.trim() || !/^\d{10}$/.test(orderData.phoneNumber)) newErrors.phoneNumber = "Phone Number must be 10 digits.";
    if (!orderData.address.trim()) newErrors.address = "Address is required.";
    if (!orderData.city.trim()) newErrors.city = "City is required.";
    if (!orderData.orderId.trim()) newErrors.orderId = "Order ID is required.";
    if (!orderData.pickupTime.trim()) newErrors.pickupTime = "Pickup Time is required.";
    if (!orderData.orderStatus.trim()) newErrors.orderStatus = "Order Status is required.";
    
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleChange = (e) => {
    const { name, value } = e.target;
    setOrderData({ ...orderData, [name]: value });
  };

  const sendData = (e) => {
    e.preventDefault();
    if (!validateForm()) return;
    axios.post("http://localhost:5000/orders/", orderData)
      .then(() => {
        alert("Order Added");
        setOrderData({
          firstName: "", lastName: "", email: "", phoneNumber: "",
          address: "", city: "", orderId: "", specialInstructions: "",
          pickupTime: "", orderStatus: "",
        });
        setOrdersChanged((prev) => !prev);
        navigate("/all-orders");
      })
      .catch((err) => alert(err));
  };

  return (
    <div className="flex items-center justify-center min-h-screen bg-cover bg-center" style={{ backgroundImage: `url(${backgroundImage})` }}>
      <div className="bg-white bg-opacity-80 p-8 rounded-lg shadow-lg max-w-3xl w-full">
        <h1 className="text-2xl font-bold text-red-700 text-center mb-6">Add Order</h1>
        <form onSubmit={sendData} className="space-y-4">
          {[ 
            { name: "firstName", type: "text", label: "First Name" },
            { name: "lastName", type: "text", label: "Last Name" },
            { name: "email", type: "email", label: "Email" },
            { name: "phoneNumber", type: "text", label: "Phone Number" },
            { name: "address", type: "text", label: "Address" },
            { name: "city", type: "text", label: "City" },
            { name: "orderId", type: "text", label: "Order ID" },
            { name: "specialInstructions", type: "text", label: "Special Instructions" },
            { name: "pickupTime", type: "datetime-local", label: "Pickup Time" },
            { name: "orderStatus", type: "text", label: "Order Status" },
          ].map((field) => (
            <div key={field.name}>
              <label className="block font-semibold" htmlFor={field.name}>{field.label}</label>
              <input
                type={field.type}
                id={field.name}
                name={field.name}
                className="w-full px-4 py-2 border border-gray-300 rounded-lg focus:ring focus:ring-red-300"
                placeholder={`Enter ${field.label}`}
                value={orderData[field.name]}
                onChange={handleChange}
              />
              {errors[field.name] && <p className="text-red-600 text-sm">{errors[field.name]}</p>}
            </div>
          ))}
          <button type="submit" className="w-full bg-red-700 text-white py-2 rounded-lg hover:bg-red-800">
            Submit
          </button>
        </form>
        <button onClick={() => navigate("/")} className="w-full mt-4 bg-gray-500 text-white py-2 rounded-lg hover:bg-gray-600">
          Back to Home
        </button>
      </div>
    </div>
  );
};

export default AddOrder;
